window.AUTH=window.AUTH||{};window.AUTH["23-824"]={"d":"23-824","id":"2024/23-824","n":"United States v. Miller","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2024-08-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/322075/20240808212316792_23-824tsUnitedStates.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondent David L. Miller","date":"2024-09-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/326364/20240919142905852_Miller%20Merits%20Brief.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner United States","date":"2024-10-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/328852/20241021163829249_23-824rbUnitedStates.pdf","side":"pet","n":59}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r21_6kh7.pdf","tr":true,"items":[{"t":"case","label":"Acequia, Inc. v. Clinton (In re Acequia, Inc.)","cite":"34 F.3d 800","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/34/800/","by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"Like Prometheus bound, the trustee is chained to the rights of [such] creditors.","cite":"34 F.3d 800, 809"}]},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"by":{"0":"14"}},{"t":"case","label":"Bull v. United States","cite":"295 U.S. 247","y":1935,"id":"scdb/1934-123","sc":1,"by":{"0":"37"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"581 U.S. 87","y":2017,"id":"2016/16-149","sc":1,"by":{"0":"27"}},{"t":"case","label":"Davis v. Willey","cite":"263 F. 588","y":1920,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F./263/588/","by":{"0":"16","2":"22"},"q":[{"src":"brief","b":0,"text":"subject to the same limitations and disabilities that would have beset the creditor in the prosecution of the action on his own behalf.","cite":"263 F. 588, 589"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"subject to the same limitations and disabilities that would have beset the creditor in the prosecution of the action on his own behalf.","cite":"263 F. 588, 589"}]},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"by":{"0":"33","1":"10, 13, 27, 27","2":"7, 12"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"no amount of legislative history can `supply a waiver that is not Page Proof Pending Publication clearly evident from the language of the statute.'","cite":"601 U. S. 42, 49"}]},{"t":"case","label":"Ebner v. Kaiser (In re Kaiser)","cite":"525 B.R. 697","y":2014,"court":"Bankr. N.D. Ill.","url":"https://www.courtlistener.com/c/B.R./525/697/","by":{"0":"13"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"by":{"0":"33, 34"},"q":[{"src":"brief","b":0,"text":"so that the Government’s consent to be sued is never enlarged beyond what a fair reading of the text requires,","cite":"566 U.S. at 290"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"construe any ambiguities in the scope of a waiver in favor of the sovereign.","cite":"566 U. S. 284, 291"}]},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"by":{"0":"10, 20, 33","1":"27-28"},"q":[{"src":"brief","b":0,"text":"whether the source of substantive law upon which the [trustee] relies provides an avenue for relief.","cite":"510 U.S. 471, 484"},{"src":"brief","b":0,"text":"Absent a waiver, sovereign immunity shields the Federal Government and its agencies from suit.","cite":"510 U.S. at 475"},{"src":"brief","b":1,"text":"both a ‘source of substantive law’ that ‘provides an avenue for relief’ and ‘a waiver of sovereign immunity.’","cite":"510 U.S. 471, 484"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"whether the source of substantive law upon which the claimant relies provides an avenue for relief.","cite":"510 U. S., at 484"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"that waivers of sovereign immunity are to be read narrowly.","cite":"510 U. S., at 480"}]},{"t":"case","label":"Hoffman v. Connecticut Dep’t of Income Maint.","cite":"492 U.S. 96","y":1989,"id":"1988/88-412","sc":1,"by":{"0":"31, 32","1":"31-32"},"q":[{"src":"brief","b":0,"text":"in direct response to two Supreme Court decisions,","cite":"492 U.S. 96"},{"src":"argument","who":"Ms. Blatt","text":"And in Hoffman, you said to Congress: You were too scattershot because you didn't list the code provisions. It just would have applied to a hundred."},{"src":"argument","who":"Ms. Blatt","text":"And after Congress made this very broad after this Court twice narrowed it, it just would be a strange thing, especially when state law's also incorporated in the very provision at issue in Hoffman, the preferential, which also relies -- it's the same -- it's the same thing."}]},{"t":"case","label":"Kurns v. Railroad Friction Prods. Corp.","cite":"565 U.S. 625","y":2012,"id":"2011/10-879","sc":1,"by":{"0":"36","1":"47"}},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"by":{"0":"33","1":"24-25, 41, 43"},"q":[{"src":"brief","b":0,"text":"Congress must make its intent . . . unmistakably clear in the language of the statute.","cite":"599 U.S. 382, 387"},{"src":"brief","b":0,"text":"This clear-statement rule is a demanding standard,","cite":"599 U.S. at 388"},{"src":"brief","b":1,"text":"articulate[] its intent in the most straightforward way.","cite":"599 U.S. 382, 394"},{"src":"brief","b":1,"text":"basic requirements generally apply to all creditors,","cite":"599 U.S. at 391"}]},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"584 U.S. 709","y":2018,"id":"2017/16-1215","sc":1,"by":{"0":"8, 26, 28","1":"8, 15-17, 42","2":"5, 6"},"q":[{"src":"brief","b":0,"text":"reach any subject that has ‘a connection with’ . . . the topics the statute enumerates.","cite":"584 U.S. 709, 717-718"},{"src":"brief","b":0,"text":"generally has a broadening effect, ensuring that the scope of a [statutory] provision covers not only its subject but also matters relating to that subject.","cite":"584 U.S. 709, 717"},{"src":"brief","b":1,"text":"clearly expresses Congress’s intent to abolish the Government’s sovereign immunity in an avoidance proceeding arising under § 544(b)(1).","cite":"584 U.S. 709, 717-18"},{"src":"brief","b":1,"text":"have long been understood as terms of breadth.","cite":"584 U.S. 709"}]},{"t":"case","label":"Mendelsohn v. Kovalchuk (In re APCO Merch. Servs., Inc.)","cite":"585 B.R. 306","y":2018,"court":"Bankr. E.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./585/306/","by":{"0":"4"},"q":[{"src":"brief","b":0,"text":"subject to the same defenses a transferee would have in a state fraudulent conveyance action brought by the actual creditor.","cite":"585 B.R. 306, 314"}]},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"583 U.S. 366","y":2018,"id":"2017/16-784","sc":1,"by":{"0":"2, 3","1":"4, 40-41"},"q":[{"src":"brief","b":0,"text":"set aside certain types of transfers and recapture the value of those avoided transfers for the benefit of the estate.","cite":"583 U.S. 366, 370"},{"src":"brief","b":0,"text":"avoid un- recorded liens and conveyances.","cite":"583 U.S. at 371"},{"src":"brief","b":1,"text":"[t]o maximize the funds available for, and ensure equity in, the distribution to creditors.","cite":"583 U.S. at 369"}]},{"t":"case","label":"Muldrow v. City of St. Louis","cite":"144 S. Ct. 967","y":2024,"id":"2023/22-193","sc":1,"by":{"0":"25","1":"34"}},{"t":"case","label":"Office of Pers. Mgmt. v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"no money can be paid out of the Treasury unless it has been appropriated by an act of Congress.","cite":"496 U.S. 414, 424"}]},{"t":"case","label":"Pattern Makers’ League of N. Am. v. NLRB","cite":"473 U.S. 95","y":1985,"id":"1984/83-1894","sc":1,"by":{"0":"27","1":"18","2":"5"}},{"t":"case","label":"Patterson v. Shumate","cite":"504 U.S. 753","y":1992,"id":"1991/91-913","sc":1,"by":{"0":"3"}},{"t":"case","label":"Presley v. Etowah Cnty. Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"by":{"0":"26","1":"18","2":"6"}},{"t":"case","label":"Sender v. Simon","cite":"84 F.3d 1299","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/84/1299/","by":{"0":"3, 14"},"q":[{"src":"brief","b":0,"text":"contains no substantive provisions indicating what transfers or obligations are avoidable,","cite":"84 F.3d 1299, 1304"},{"src":"brief","b":0,"text":"substantive provisions indicating what transfers or obligations are avoidable.","cite":"84 F.3d 1299, 1304"}]},{"t":"case","label":"Sigmon v. Southwest Airlines Co.","cite":"110 F.3d 1200","y":1997,"url":"https://www.courtlistener.com/c/F.3d/110/1200/","by":{"0":"36"}},{"t":"case","label":"The Official Comm. of Unsecured Creditors of Cybergenics Corp. v. Chinery (In re Cybergenics Corp.)","cite":"226 F.3d 237","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/226/237/","by":{"0":"15"},"q":[{"src":"brief","b":0,"text":"a trustee * * * can use this power only if there is an unsecured creditor of the debtor that actually has the requisite nonbankruptcy cause of action.","cite":"226 F.3d 237, 243"}]},{"t":"case","label":"Umland v. PLANCO Fin. Servs., Inc.","cite":"542 F.3d 59","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/542/59/","by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"confers upon the creditor the right to disregard the conveyance and realize his debt out of the affected asset as though the transfer had not been made.","cite":"542 F.3d 59, 67"}]},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"exceedingly strong interest in financial stability","cite":"553 U.S. 1, 12"}]},{"t":"case","label":"United States v. LMS Holding Co. (In re LMS Holding Co.)","cite":"50 F.3d 1526","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/50/1526/","by":{"0":"30"}},{"t":"case","label":"United States v. Mitchell","cite":"403 U.S. 190","y":1971,"id":"1970/798","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"by":{"0":"17, 31-33","1":"31-32, 31","2":"12"},"q":[{"src":"brief","b":1,"text":"to declare that [a tax] transfer to [the] IRS was voidable.","cite":"503 U.S. 30"}]},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"by":{"0":"34"}},{"t":"case","label":"United States Postal Serv. v. Flamingo Indus. (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"by":{"0":"20","1":"28"}},{"t":"case","label":"Zazzali v. United States (In re DBSI, Inc.)","cite":"869 F.3d 1004","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/1004/","by":{"0":"4, 8, 9, 17, 40","1":"14, 16, 19, 21, 30, 43, 48"},"q":[{"src":"brief","b":0,"text":"never meaningfully addressed the scope of § 106(a) as reflected in its text,","cite":"869 F.3d at 1009"},{"src":"brief","b":0,"text":"succeed[ed] for any reason—whether due to the statute of limitations, estoppel, res judicata, waiver, or any other defense—then the trustee is similarly barred and cannot avoid the transfer.","cite":"869 F.3d 1004, 1009"},{"src":"brief","b":1,"text":"It simply does not matter how a sovereign immunity defense is invoked against [the] Trustee’s claims because Section 106(a)(1) eliminates the obstacle wherever it appears ‘with respect to’ § 544.","cite":"869 F.3d at 1010"},{"src":"brief","b":1,"text":"essentially nullif[ies] Section 106(a)(1)’s effect on Section 544(b)(1)","cite":"869 F.3d at 1011"}]},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"0":"18, 37","1":"12, 39, 45, 48-49"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"12, 18, 23"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(41)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30, 30","1":"13, 20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"department, agency, or instrumentality of the United States.","cite":"11 U. S. C. § 101(27)"}]},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)","(a)(1)","(a)(2)","(a)(5)"],"stext":{"head":"§106. Waiver of sovereign immunity","paras":[[0,"(a) Notwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit to the extent set forth in this section with respect to the following:"],[1,"(1) Sections 105, 106, 107, 108, 303, 346, 362, 363, 364, 365, 366, 502, 503, 505, 506, 510, 522, 523, 524, 525, 542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 722, 724, 726, 744, 749, 764, 901, 922, 926, 928, 929, 944, 1107, 1141, 1142, 1143, 1146, 1201, 1203, 1205, 1206, 1227, 1231, 1301, 1303, 1305, and 1327 of this title."],[1,"(2) The court may hear and determine any issue arising with respect to the application of such sections to governmental units."],[1,"(3) The court may issue against a governmental unit an order, process, or judgment under such sections or the Federal Rules of Bankruptcy Procedure, including an order or judgment awarding a money recovery, but not including an award of punitive damages. Such order or judgment for costs or fees under this title or the Federal Rules of Bankruptcy Procedure against any governmental unit shall be consistent with the provisions and limitations of section 2412(d)(2)(A) of title 28."],[1,"(4) The enforcement of any such order, process, or judgment against any governmental unit shall be consistent with appropriate nonbankruptcy law applicable to such governmental unit and, in the case of a money judgment against the United States, shall be paid as if it is a judgment rendered by a district court of the United States."],[1,"(5) Nothing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law."],[0,"(b) A governmental unit that has filed a proof of claim in the case is deemed to have waived sovereign immunity with respect to a claim against such governmental unit that is property of the estate and that arose out of the same transaction or occurrence out of which the claim of such governmental unit arose."],[0,"(c) Notwithstanding any assertion of sovereign immunity by a governmental unit, there shall be offset against a claim or interest of a governmental unit any claim against such governmental unit that is property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/106?type=usc&year=mostrecent&link-type=html"},"by":{"0":"29, 29, 29, 29, 30, 30","2":"12, 13, 2, 3, 5-12, 14, 16-21, 3, 6-8, 3, 7, 3, 2, 3, 5-8"},"q":[{"src":"brief","b":0,"text":"to the extent set forth in this section.","cite":"11 U.S.C. 106(a)"},{"src":"brief","b":0,"text":"[n]othing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law.","cite":"11 U.S.C. 106(a)(5)"},{"src":"brief","b":2,"text":"to the extent set forth in this section.","cite":"11 U.S.C. 106(a)(1)"},{"src":"brief","b":2,"text":"create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law.","cite":"11 U.S.C. 106(a)(5)"}]},{"t":"usc","label":"11 U.S.C. § 303","url":"https://www.law.cornell.edu/uscode/text/11/303","subs":["(a)","(i)"],"by":{"0":"30, 30, 30"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","by":{"0":"15","2":"8"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(2)(A)","(a)(1)(B)(ii)","(a)(19)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26","2":"8, 9"},"q":[{"src":"brief","b":0,"text":"statement respecting the debtor’s * * * financial condition","cite":"11 U.S.C. 523(a)(2)(A)"}]},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(c)(2)"],"by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","subs":["(b)"],"by":{"0":"32"}},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","subs":["(a)","(b)","(b)(1)","(b)(2)"],"stext":{"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","paras":[[0,"(a) The trustee shall have, as of the commencement of the case, and without regard to any knowledge of the trustee or of any creditor, the rights and powers of, or may avoid any transfer of property of the debtor or any obligation incurred by the debtor that is voidable by—"],[1,"(1) a creditor that extends credit to the debtor at the time of the commencement of the case, and that obtains, at such time and with respect to such credit, a judicial lien on all property on which a creditor on a simple contract could have obtained such a judicial lien, whether or not such a creditor exists;"],[1,"(2) a creditor that extends credit to the debtor at the time of the commencement of the case, and obtains, at such time and with respect to such credit, an execution against the debtor that is returned unsatisfied at such time, whether or not such a creditor exists; or"],[1,"(3) a bona fide purchaser of real property, other than fixtures, from the debtor, against whom applicable law permits such transfer to be perfected, that obtains the status of a bona fide purchaser and has perfected such transfer at the time of the commencement of the case, whether or not such a purchaser exists."],[0,"(b)(1) Except as provided in paragraph (2), the trustee may avoid any transfer of an interest of the debtor in property or any obligation incurred by the debtor that is voidable under applicable law by a creditor holding an unsecured claim that is allowable under section 502 of this title or that is not allowable only under section 502(e) of this title."],[0,"(2) Paragraph (1) shall not apply to a transfer of a charitable contribution (as that term is defined in section 548(d)(3)) that is not covered under section 548(a)(1)(B), by reason of section 548(a)(2). Any claim by any person to recover a transferred contribution described in the preceding sentence under Federal or State law in a Federal or State court shall be preempted by the commencement of the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/544?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 2, 22, 22, 22","2":"2, 10, 11, 1-5, 7, 8, 10-14, 16-19, 21-23, 4, 24"},"q":[{"src":"brief","b":0,"text":"whether or not such a creditor exists.","cite":"11 U.S.C. 544(a)"},{"src":"brief","b":0,"text":"voidable under applicable law by a creditor holding an unsecured claim.","cite":"11 U.S.C. 544(b)(1)"},{"src":"brief","b":2,"text":"voidable under applicable law by a creditor.","cite":"11 U.S.C. 544(b)(1)"},{"src":"argument","who":"Ms. Dubin","text":"When Congress was identifying sections for which the waiver of immunity would operate, of course, it would include Section 544. But I think it is also crystal-clear that Congress would not have thought that that waiver of immunity would expose the IRS stub -- substantive state liability under 544(b), and that's because Congress specifically said in the waiver that nothing in this section creates any substantive claim for relief that doesn't otherwise exist."},{"src":"argument","who":"Justice Jackson","text":"No, no, no. 106(a) absolutely refers to the Section 544. It's in there."}]},{"t":"usc","label":"11 U.S.C. § 546","url":"https://www.law.cornell.edu/uscode/text/11/546","subs":["(a)(1)"],"by":{"0":"22"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","subs":["(b)","(a)(2)","(c)"],"stext":{"head":"§547. Preferences","paras":[[0,"(a) In this section—"],[1,"(1) \"inventory\" means personal property leased or furnished, held for sale or lease, or to be furnished under a contract for service, raw materials, work in process, or materials used or consumed in a business, including farm products such as crops or livestock, held for sale or lease;"],[1,"(2) \"new value\" means money or money's worth in goods, services, or new credit, or release by a transferee of property previously transferred to such transferee in a transaction that is neither void nor voidable by the debtor or the trustee under any applicable law, including proceeds of such property, but does not include an obligation substituted for an existing obligation;"],[1,"(3) \"receivable\" means right to payment, whether or not such right has been earned by performance; and"],[1,"(4) a debt for a tax is incurred on the day when such tax is last payable without penalty, including any extension."],[0,"(b) Except as provided in subsections (c) and (i) of this section, the trustee may, based on reasonable due diligence in the circumstances of the case and taking into account a party's known or reasonably knowable affirmative defenses under subsection (c), avoid any transfer of an interest of the debtor in property—"],[1,"(1) to or for the benefit of a creditor;"],[1,"(2) for or on account of an antecedent debt owed by the debtor before such transfer was made;"],[1,"(3) made while the debtor was insolvent;"],[1,"(4) made—"],[2,"(A) on or within 90 days before the date of the filing of the petition; or"],[2,"(B) between ninety days and one year before the date of the filing of the petition, if such creditor at the time of such transfer was an insider; and"],[1,"(5) that enables such creditor to receive more than such creditor would receive if—"],[2,"(A) the case were a case under chapter 7 of this title;"],[2,"(B) the transfer had not been made; and"],[2,"(C) such creditor received payment of such debt to the extent provided by the provisions of this title."],[0,"(c) The trustee may not avoid under this section a transfer—"],[1,"(1) to the extent that such transfer was—"],[2,"(A) intended by the debtor and the creditor to or for whose benefit such transfer was made to be a contemporaneous exchange for new value given to the debtor; and"],[2,"(B) in fact a substantially contemporaneous exchange;"],[1,"(2) to the extent that such transfer was in payment of a debt incurred by the debtor in the ordinary course of business or financial affairs of the debtor and the transferee, and such transfer was—"],[2,"(A) made in the ordinary course of business or financial affairs of the debtor and the transferee; or"],[2,"(B) made according to ordinary business terms;"],[1,"(3) that creates a security interest in property acquired by the debtor—"],[2,"(A) to the extent such security interest secures new value that was—"],[3,"(i) given at or after the signing of a security agreement that contains a description of such property as collateral;"],[3,"(ii) given by or on behalf of the secured party under such agreement;"],[3,"(iii) given to enable the debtor to acquire such property; and"],[3,"(iv) in fact used by the debtor to acquire such property; and"],[2,"(B) that is perfected on or before 30 days after the debtor receives possession of such property;"],[1,"(4) to or for the benefit of a creditor, to the extent that, after such transfer, such creditor gave new value to or for the benefit of the debtor—"],[2,"(A) not secured by an otherwise unavoidable security interest; and"],[2,"(B) on account of which new value the debtor did not make an otherwise unavoidable transfer to or for the benefit of such creditor;"],[1,"(5) that creates a perfected security interest in inventory or a receivable or the proceeds of either, except to the extent that the aggregate of all such transfers to the transferee caused a reduction, as of the date of the filing of the petition and to the prejudice of other creditors holding unsecured claims, of any amount by which the debt secured by such security interest exceeded the value of all security interests for such debt on the later of—"],[2,"(A)(i) with respect to a transfer to which subsection (b)(4)(A) of this section applies, 90 days before the date of the filing of the petition; or"],[2,"(ii) with respect to a transfer to which subsection (b)(4)(B) of this section applies, one year before the date of the filing of the petition; or"],[2,"(B) the date on which new value was first given under the security agreement creating such security interest;"],[1,"(6) that is the fixing of a statutory lien that is not avoidable under section 545 of this title;"],[1,"(7) to the extent such transfer was a bona fide payment of a debt for a domestic support obligation;"],[1,"(8) if, in a case filed by an individual debtor whose debts are primarily consumer debts, the aggregate value of all property that constitutes or is affected by such transfer is less than $600; or"],[1,"(9) if, in a case filed by a debtor whose debts are not primarily consumer debts, the aggregate value of all property that constitutes or is affected by such transfer is less than $5,000.1"],[0,"(d) The trustee may avoid a transfer of an interest in property of the debtor transferred to or for the benefit of a surety to secure reimbursement of such a surety that furnished a bond or other obligation to dissolve a judicial lien that would have been avoidable by the trustee under subsection (b) of this section. The liability of such surety under such bond or obligation shall be discharged to the extent of the value of such property recovered by the trustee or the amount paid to the trustee."],[0,"(e)(1) For the purposes of this section—"],[1,"(A) a transfer of real property other than fixtures, but including the interest of a seller or purchaser under a contract for the sale of real property, is perfected when a bona fide purchaser of such property from the debtor against whom applicable law permits such transfer to be perfected cannot acquire an interest that is superior to the interest of the transferee; and"],[1,"(B) a transfer of a fixture or property other than real property is perfected when a creditor on a simple contract cannot acquire a judicial lien that is superior to the interest of the transferee."],[0,"(2) For the purposes of this section, except as provided in paragraph (3) of this subsection, a transfer is made—"],[1,"(A) at the time such transfer takes effect between the transferor and the transferee, if such transfer is perfected at, or within 30 days after, such time, except as provided in subsection (c)(3)(B);"],[1,"(B) at the time such transfer is perfected, if such transfer is perfected after such 30 days; or"],[1,"(C) immediately before the date of the filing of the petition, if such transfer is not perfected at the later of—"],[2,"(i) the commencement of the case; or"],[2,"(ii) 30 days after such transfer takes effect between the transferor and the transferee."],[0,"(3) For the purposes of this section, a transfer is not made until the debtor has acquired rights in the property transferred."],[0,"(f) For the purposes of this section, the debtor is presumed to have been insolvent on and during the 90 days immediately preceding the date of the filing of the petition."],[0,"(g) For the purposes of this section, the trustee has the burden of proving the avoidability of a transfer under subsection (b) of this section, and the creditor or party in interest against whom recovery or avoidance is sought has the burden of proving the nonavoidability of a transfer under subsection (c) of this section."],[0,"(h) The trustee may not avoid a transfer if such transfer was made as a part of an alternative repayment schedule between the debtor and any creditor of the debtor created by an approved nonprofit budget and credit counseling agency."],[0,"(i) If the trustee avoids under subsection (b) a transfer made between 90 days and 1 year before the date of the filing of the petition, by the debtor to an entity that is not an insider for the benefit of a creditor that is an insider, such transfer shall be considered to be avoided under this section only with respect to the creditor that is an insider."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/547?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 32","2":"9, 9, 9, 9"},"q":[{"src":"brief","b":2,"text":"voidable * * * under any applicable law.","cite":"11 U.S.C. 547(a)(2)"}]},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(a)","(a)(2)"],"stext":{"head":"§548. Fraudulent transfers and obligations","paras":[[0,"(a)(1) The trustee may avoid any transfer (including any transfer to or for the benefit of an insider under an employment contract) of an interest of the debtor in property, or any obligation (including any obligation to or for the benefit of an insider under an employment contract) incurred by the debtor, that was made or incurred on or within 2 years before the date of the filing of the petition, if the debtor voluntarily or involuntarily—"],[1,"(A) made such transfer or incurred such obligation with actual intent to hinder, delay, or defraud any entity to which the debtor was or became, on or after the date that such transfer was made or such obligation was incurred, indebted; or"],[1,"(B)(i) received less than a reasonably equivalent value in exchange for such transfer or obligation; and"],[1,"(ii)(I) was insolvent on the date that such transfer was made or such obligation was incurred, or became insolvent as a result of such transfer or obligation;"],[1,"(II) was engaged in business or a transaction, or was about to engage in business or a transaction, for which any property remaining with the debtor was an unreasonably small capital;"],[1,"(III) intended to incur, or believed that the debtor would incur, debts that would be beyond the debtor's ability to pay as such debts matured; or"],[1,"(IV) made such transfer to or for the benefit of an insider, or incurred such obligation to or for the benefit of an insider, under an employment contract and not in the ordinary course of business."],[0,"(2) A transfer of a charitable contribution to a qualified religious or charitable entity or organization shall not be considered to be a transfer covered under paragraph (1)(B) in any case in which—"],[1,"(A) the amount of that contribution does not exceed 15 percent of the gross annual income of the debtor for the year in which the transfer of the contribution is made; or"],[1,"(B) the contribution made by a debtor exceeded the percentage amount of gross annual income specified in subparagraph (A), if the transfer was consistent with the practices of the debtor in making charitable contributions."],[0,"(b) The trustee of a partnership debtor may avoid any transfer of an interest of the debtor in property, or any obligation incurred by the debtor, that was made or incurred on or within 2 years before the date of the filing of the petition, to a general partner in the debtor, if the debtor was insolvent on the date such transfer was made or such obligation was incurred, or became insolvent as a result of such transfer or obligation."],[0,"(c) Except to the extent that a transfer or obligation voidable under this section is voidable under section 544, 545, or 547 of this title, a transferee or obligee of such a transfer or obligation that takes for value and in good faith has a lien on or may retain any interest transferred or may enforce any obligation incurred, as the case may be, to the extent that such transferee or obligee gave value to the debtor in exchange for such transfer or obligation."],[0,"(d)(1) For the purposes of this section, a transfer is made when such transfer is so perfected that a bona fide purchaser from the debtor against whom applicable law permits such transfer to be perfected cannot acquire an interest in the property transferred that is superior to the interest in such property of the transferee, but if such transfer is not so perfected before the commencement of the case, such transfer is made immediately before the date of the filing of the petition."],[0,"(2) In this section—"],[1,"(A) \"value\" means property, or satisfaction or securing of a present or antecedent debt of the debtor, but does not include an unperformed promise to furnish support to the debtor or to a relative of the debtor;"],[1,"(B) a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency that receives a margin payment, as defined in section 101, 741, or 761 of this title, or settlement payment, as defined in section 101 or 741 of this title, takes for value to the extent of such payment;"],[1,"(C) a repo participant or financial participant that receives a margin payment, as defined in section 741 or 761 of this title, or settlement payment, as defined in section 741 of this title, in connection with a repurchase agreement, takes for value to the extent of such payment;"],[1,"(D) a swap participant or financial participant that receives a transfer in connection with a swap agreement takes for value to the extent of such transfer; and"],[1,"(E) a master netting agreement participant that receives a transfer in connection with a master netting agreement or any individual contract covered thereby takes for value to the extent of such transfer, except that, with respect to a transfer under any individual contract covered thereby, to the extent that such master netting agreement participant otherwise did not take (or is otherwise not deemed to have taken) such transfer for value."],[0,"(3) In this section, the term \"charitable contribution\" means a charitable contribution, as that term is defined in section 170(c) of the Internal Revenue Code of 1986, if that contribution—"],[1,"(A) is made by a natural person; and"],[1,"(B) consists of—"],[2,"(i) a financial instrument (as that term is defined in section 731(c)(2)(C) of the Internal Revenue Code of 1986); or"],[2,"(ii) cash."],[0,"(4) In this section, the term \"qualified religious or charitable entity or organization\" means—"],[1,"(A) an entity described in section 170(c)(1) of the Internal Revenue Code of 1986; or"],[1,"(B) an entity or organization described in section 170(c)(2) of the Internal Revenue Code of 1986."],[0,"(e)(1) In addition to any transfer that the trustee may otherwise avoid, the trustee may avoid any transfer of an interest of the debtor in property that was made on or within 10 years before the date of the filing of the petition, if—"],[1,"(A) such transfer was made to a self-settled trust or similar device;"],[1,"(B) such transfer was by the debtor;"],[1,"(C) the debtor is a beneficiary of such trust or similar device; and"],[1,"(D) the debtor made such transfer with actual intent to hinder, delay, or defraud any entity to which the debtor was or became, on or after the date that such transfer was made, indebted."],[0,"(2) For the purposes of this subsection, a transfer includes a transfer made in anticipation of any money judgment, settlement, civil penalty, equitable order, or criminal fine incurred by, or which the debtor believed would be incurred by—"],[1,"(A) any violation of the securities laws (as defined in section 3(a)(47) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(47))), any State securities laws, or any regulation or order issued under Federal securities laws or State securities laws; or"],[1,"(B) fraud, deceit, or manipulation in a fiduciary capacity or in connection with the purchase or sale of any security registered under section 12 or 15(d) of the Securities Exchange Act of 1934 (15 U.S.C. 78l and 78o(d)) or under section 6 of the Securities Act of 1933 (15 U.S.C. 77f)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/548?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 38, 2, 5, 32","2":"1, 8, 10, 1, 10, 24"},"q":[{"src":"argument","who":"Ms. Dubin","text":"Chief Justice, and may it please the Court: The Bankruptcy Code get -- grants trustees an array of avoidance powers, including the power to avoid fraudulent transfers under Section 548, subject to a two-year federal lookback period."},{"src":"argument","who":"Ms. Dubin","text":"But Congress also passed a federal fraudulent transfer provision in Section 548, and it selected a two-year lookback period. And there's every reason to think that Congress intended that lookback period to apply to the IRS, not indeterminate limitations periods set by 50 states."}]},{"t":"usc","label":"11 U.S.C. § 549","url":"https://www.law.cornell.edu/uscode/text/11/549","subs":["(a)"],"by":{"0":"2, 32","2":"8, 13"},"q":[{"src":"brief","b":0,"text":"that occurs after the commencement of the case.","cite":"11 U.S.C. 549(a)"}]},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(a)","(b)","(d)"],"by":{"0":"12, 39","2":"20, 23, 24, 23, 24, 16"}},{"t":"usc","label":"26 U.S.C. § 6323","url":"https://www.law.cornell.edu/uscode/text/26/6323","by":{"0":"30"}},{"t":"usc","label":"26 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/26/6511","subs":["(a)"],"by":{"0":"38"}},{"t":"usc","label":"26 U.S.C. § 6532","url":"https://www.law.cornell.edu/uscode/text/26/6532","by":{"0":"38"}},{"t":"usc","label":"26 U.S.C. § 7421","url":"https://www.law.cornell.edu/uscode/text/26/7421","subs":["(a)","(b)"],"by":{"0":"35, 35"},"q":[{"src":"brief","b":0,"text":"no suit for the purpose of restraining the assessment or collection of any tax shall be maintained in any court by any person, whether or not such person is the person against whom such tax was assessed.","cite":"26 U.S.C. 7421(a)"},{"src":"brief","b":0,"text":"[n]o suit shall be maintained in any court for the purpose of restraining the assessment or collection [of ] * * * the amount of the liability, at law or in equity, of a transferee of property * * * in respect of any internal revenue tax.","cite":"26 U.S.C. 7421(b)"}]},{"t":"usc","label":"26 U.S.C. § 7422","url":"https://www.law.cornell.edu/uscode/text/26/7422","subs":["(a)"],"by":{"0":"35"}},{"t":"usc","label":"26 U.S.C. § 7426","url":"https://www.law.cornell.edu/uscode/text/26/7426","subs":["(a)(3)","(a)(4)"],"by":{"0":"39, 36, 36"}},{"t":"usc","label":"28 U.S.C. § 1409","url":"https://www.law.cornell.edu/uscode/text/28/1409","by":{"0":"17","1":"29"}},{"t":"case","label":"Acme Harvester Co. v. Beekman Lumber Co.","cite":"222 U.S. 300","y":1911,"id":"scdb/1911-024","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"place the property of the bankrupt under the control of the court, wherever it is found, with a view to its equal distribution among the creditors.","cite":"222 U.S. 300, 307"}]},{"t":"case","label":"Allen v. Cooper","cite":"589 U.S. 248","y":2020,"id":"2019/18-877","sc":1,"by":{"1":"32-33","2":"14"},"q":[{"src":"brief","b":1,"text":"[i]n bankruptcy, … sovereign immunity has no place.","cite":"589 U.S. 248, 257"},{"src":"brief","b":2,"text":"the idea that federal courts could impose on state sovereignty.","cite":"589 U.S. 248, 258"}]},{"t":"case","label":"Armed Forces Bank NA v. Dragoo","cite":"2018 WL 8621584","y":2018,"court":"D. Ariz. Sept. 28","by":{"1":"36"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"by":{"1":"34"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"by":{"1":"28"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"by":{"1":"39"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"do[] not implicate States’ sovereignty to nearly the same degree as other kinds of jurisdiction.","cite":"546 U.S. 356, 362"}]},{"t":"case","label":"CFTC v. Weintraub","cite":"471 U.S. 343","y":1985,"id":"1984/84-261","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"duty to maximize the value of the estate.","cite":"471 U.S. 343, 352"}]},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"by":{"1":"39"}},{"t":"case","label":"Cook v. United States (In re Yahweh Ctr., Inc.)","cite":"27 F.4th 960","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/27/960/","by":{"1":"19, 40"},"q":[{"src":"brief","b":1,"text":"‘issue arising with respect to’ applying § 544 against the United States.","cite":"27 F.4th 960, 966"}]},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"by":{"1":"14"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"not limited to the precise arguments … made below.","cite":"554 U.S. 471, 487"}]},{"t":"case","label":"Georgelas v. Desert Hill Ventures, Inc.","cite":"45 F.4th 1193","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/1193/","by":{"1":"36"}},{"t":"case","label":"Gobeille v. Liberty Mut. Ins. Co.","cite":"577 U.S. 312","y":2016,"id":"2015/14-181","sc":1,"by":{"1":"45-46"}},{"t":"case","label":"Hafen v. Taylor","cite":"2021 WL 3194367","y":2021,"court":"D. Utah July 28","by":{"1":"36"}},{"t":"case","label":"Hemphill v. New York","cite":"595 U.S. 140","y":2022,"id":"2021/20-637","sc":1,"by":{"1":"37"}},{"t":"case","label":"Hughes v. Talen Energy Mktg., LLC","cite":"578 U.S. 150","y":2016,"id":"2015/14-614","sc":1,"by":{"1":"46-47"},"q":[{"src":"brief","b":1,"text":"[T]he purpose of Congress is the ultimate touchstone in every pre-emption case.","cite":"578 U.S. 150, 163"}]},{"t":"case","label":"Husky Int’l Elecs., Inc. v. Ritz","cite":"578 U.S. 355","y":2016,"id":"2015/15-145","sc":1,"by":{"1":"4"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"by":{"1":"45, 47"}},{"t":"case","label":"Kimel v. Fla. Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"make[] it more than clear that Congress understood the consequences of its actions","cite":"528 U.S. 62, 76"}]},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"by":{"1":"3, 42"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"1":"37-38"}},{"t":"case","label":"Mission Prod. Holdings, Inc. v. Tempnology, LLC","cite":"587 U.S. 370","y":2019,"id":"2018/17-1657","sc":1,"by":{"1":"3-4, 40"},"q":[{"src":"brief","b":1,"text":"the pot out of which creditors’ claims are paid.","cite":"587 U.S. 370, 373"},{"src":"brief","b":1,"text":"something-for-nothing transfers that deplete the estate (and so cheat creditors).","cite":"587 U.S. at 382"}]},{"t":"case","label":"Ohio Adjutant Gen.’s Dep’t v. FLRA","cite":"598 U.S. 449","y":2023,"id":"2022/21-1454","sc":1,"by":{"1":"38, 38","2":"20"}},{"t":"case","label":"Oliphant v. Moore","cite":"293 S.W. 541","y":1927,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./293/541/","by":{"1":"35"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"575 U.S. 373","y":2015,"id":"2014/13-271","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"directed at … precisely the things over which [federal law] has comprehensive authority","cite":"575 U.S. 373, 385-87"}]},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"by":{"1":"17"}},{"t":"case","label":"Polselli v. IRS","cite":"598 U.S. 432","y":2023,"id":"2022/21-1599","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"considerable power to go after unpaid taxes.","cite":"598 U.S. 432, 434"}]},{"t":"case","label":"Pugin v. Garland","cite":"599 U.S. 600","y":2023,"id":"2022/22-23","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"offenses that have ‘a connection with’ obstruction of justice,","cite":"599 U.S. 600, 607"}]},{"t":"case","label":"Sargeant v. Al Saleh","cite":"512 S.W.3d 399","y":2016,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/512/399/","by":{"1":"35"}},{"t":"case","label":"Siegel v. Fitzgerald","cite":"596 U.S. 464","y":2022,"id":"2021/21-441","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"arbitrary geographically disparate treatment of debtors.","cite":"596 U.S. at 476"}]},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"by":{"1":"25-26"},"q":[{"src":"brief","b":1,"text":"Congress may recognize the laws of the state in certain particulars, although such recognition may lead to different results in different states.","cite":"245 U.S. 605, 613"}]},{"t":"case","label":"Sugartown Worldwide LLC v. Shanks","cite":"2015 WL 1312572","y":2015,"court":"E.D. Pa. Mar. 24","by":{"1":"36"}},{"t":"case","label":"Tabor v. Davis (In re Davis)","cite":"2016 WL 11696269","y":2016,"court":"Bankr. W.D. Tenn. June 15","by":{"1":"36-37"}},{"t":"case","label":"Tenn. Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"a student loan debt does not implicate a State’s Eleventh Amendment immunity.","cite":"541 U.S. 440, 445"}]},{"t":"case","label":"United States v. Brosnan","cite":"363 U.S. 237","y":1960,"id":"1959/137","sc":1,"by":{"1":"22"}},{"t":"case","label":"United States v. Mitchell","cite":"463 U.S. 206","y":1983,"id":"1982/81-1748","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"need not provide a second waiver of sovereign immunity","cite":"463 U.S. 206, 218-19"}]},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"by":{"1":"38-39"}},{"t":"case","label":"United States v. Tohono O’odham Nation","cite":"563 U.S. 307","y":2011,"id":"2010/09-846","sc":1,"by":{"1":"16"}},{"t":"case","label":"United States v. Whiting Pools, Inc.","cite":"462 U.S. 198","y":1983,"id":"1982/82-215","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"provide[d] protection to tax collectors, such as the IRS, through grants of enhanced priorities for unsecured tax claims … and by the nondischarge of tax liabilities.","cite":"462 U.S. 198, 209"}]},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"1":"34"}},{"t":"case","label":"Wells Fargo Bank v. Akanan","cite":"2021 WL 12203532","y":2021,"court":"W.D. Pa. June 15","by":{"1":"35"}},{"t":"case","label":"Woods & Erickson, LLP v. Leonard (In re AVI, Inc.)","cite":"389 B.R. 721","y":2008,"court":"B.A.P. 9th Cir.","url":"https://www.courtlistener.com/c/B.R./389/721/","by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"Avoidability is an attribute of the transfer and not the party.","cite":"389 B.R. 721, 733"}]},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"33"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"1":"15"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","by":{"1":"6, 41"}},{"t":"usc","label":"11 U.S.C. § 764","url":"https://www.law.cornell.edu/uscode/text/11/764","by":{"1":"4, 14"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","by":{"1":"16"}},{"t":"usc","label":"20 U.S.C. § 1403","url":"https://www.law.cornell.edu/uscode/text/20/1403","by":{"1":"16"}},{"t":"usc","label":"26 U.S.C. § 6321","url":"https://www.law.cornell.edu/uscode/text/26/6321","by":{"1":"44"}},{"t":"usc","label":"31 U.S.C. § 3104","url":"https://www.law.cornell.edu/uscode/text/31/3104","by":{"1":"49"}},{"t":"case","label":"Resp. Br., Ohio Adjutant Gen.’s Dep’t v. FLRA","cite":"21 F.4th 401","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/21/401/","by":{"1":"38"}},{"t":"case","label":"U.S. Br., Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"‘make any argument in support of [a] claim’ without being ‘limited to the precise arguments [it] made below.’","cite":"531 U.S. 198"}]},{"t":"case","label":"U.S. Br., Lamar, Archer & Cofrin, LLP v. Appling","cite":"584 U.S. 709","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/709/","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"clearly expresses Congress’s intent to abolish the Government’s sovereign immunity in an avoidance proceeding arising under § 544(b)(1).","cite":"584 U.S. 709, 717-18"},{"src":"brief","b":1,"text":"have long been understood as terms of breadth.","cite":"584 U.S. 709"}]},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"by":{"2":"18"}},{"t":"case","label":"Cameron v. EMW Women’s Surgical Ctr., P.S.C.","cite":"595 U.S. 267","y":2022,"id":"2021/20-601","sc":1,"by":{"2":"19"}},{"t":"case","label":"Dewsnup v. Timm","cite":"502 U.S. 410","y":1992,"id":"1991/90-741","sc":1,"by":{"2":"24"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"the kind of relationship required, its nature and strength, will be informed by context.","cite":"599 U.S. 110, 118119"},{"src":"argument","who":"Chief Justice Roberts","text":"We'll hear argument next in Case 23-824, United States versus Miller. Ms. Dubin. ORAL ARGUMENT OF YAIRA DUBIN ON BEHALF OF THE PETITIONER"},{"src":"argument","who":"Justice Gorsuch","text":"Dubin, I'm -- I actually wanted to follow up on the -- the first question that Justice Barrett asked you, and I'm -- I understand your response is that the waiver in 106 will still do work with respect to 544(a) even if it does no work with respect to 544(b)."},{"src":"argument","who":"Justice Jackson","text":"Dubin, and -- and you -- you say this actual creditor requirement, which everyone acknowledges exists in 544(b), is there for a reason. And I've been struggling with that, and I want your reaction to -- to this."}]},{"t":"case","label":"Financial Oversight & Management Board for Puerto Rico v. Centro de Periodismo Investigativo","cite":"598 U.S. 339","y":2023,"id":"2022/22-96","sc":1,"by":{"2":"20, 21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"Under long-settled law, Congress must use unmistakable language to abrogate sovereign immunity.","cite":"598 U. S. 339, 342"}]},{"t":"case","label":"Genova v. Gottlieb (In re Orange Cnty. Sanitation, Inc.)","cite":"221 B.R. 323","y":1997,"court":"Bankr. S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./221/323/","by":{"2":"24"}},{"t":"case","label":"(I) Cases—Continued: Lee v. Schweiker","cite":"739 F.2d 870","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/739/870/","by":{"2":"13"}},{"t":"case","label":"M. Fabrikant & Sons, Inc. v. JP Morgan Chase Bank (In re M. Fabrikant & Sons, Inc.)","cite":"394 B.R. 721","y":2008,"court":"Bankr. S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./394/721/","by":{"2":"24"}},{"t":"case","label":"Securities Investor Prot. Corp. v. Bernard L. Madoff Inv. Securities LLC","cite":"501 B.R. 26","y":2013,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./501/26/","by":{"2":"24"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"2":"10"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"2":"12"}},{"t":"usc","label":"5 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/5/7103","subs":["(a)(3)"],"by":{"2":"20"}},{"t":"usc","label":"11 U.S.C. § 510","url":"https://www.law.cornell.edu/uscode/text/11/510","subs":["(a)","(c)"],"by":{"2":"9, 9, 9"}},{"t":"usc","label":"11 U.S.C. § 522","url":"https://www.law.cornell.edu/uscode/text/11/522","subs":["(c)(1)"],"by":{"2":"9"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/11/1227","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/11/1327","by":{"2":"8"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)"],"by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)(1)"],"by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","by":{"2":"17"}},{"t":"usc","label":"28 U.S.C. § 2410","url":"https://www.law.cornell.edu/uscode/text/28/2410","subs":["(a)"],"by":{"2":"11"}}]};